```rust
mod test {
    #[test]
    fn test() {
        use std::time::SystemTime;

        use super::*;
        let rs = ahash::RandomState::new();

        fn time_it<F: Fn() -> T, T>(f: F, n: u32) -> u128 {
            let start = SystemTime::now();
            for _ in 0..n {
                f();
            }
            let end = SystemTime::now();
            let duration = end.duration_since(start).unwrap();
            return duration.as_millis();
        }

        let x: i32 = 10;
        let x_wrapped = TotalOrdWrap(x);
        let n_iterations = 30_000_000;

        for _ in 0..20 {
            let hash_one_t = time_it(|| rs.clone().hash_one(x), n_iterations);
            let hash_one_wrapped_t = time_it(|| rs.clone().hash_one(x_wrapped), n_iterations);
            println!(
                "hash_one(x) vs hash_one(x_wrapped): {}ms vs {}ms",
                hash_one_t, hash_one_wrapped_t
            );
        }
    }
}
```

I wasn't sure before, but now it looks like the `ToTotalOrd::to_total_ord` trait definitely helps with performance:

(the time on every line is measuring the time needed to hash the same i32 30 million times)
```
hash_one(x) vs hash_one(x_wrapped) vs hash_one(x.to_total_ord()) vs hash_one(x_tot): 1511ms vs 1973ms vs 1807ms vs 1574ms
hash_one(x) vs hash_one(x_wrapped) vs hash_one(x.to_total_ord()) vs hash_one(x_tot): 1480ms vs 1975ms vs 1721ms vs 1571ms
hash_one(x) vs hash_one(x_wrapped) vs hash_one(x.to_total_ord()) vs hash_one(x_tot): 1476ms vs 1932ms vs 1695ms vs 1542ms
hash_one(x) vs hash_one(x_wrapped) vs hash_one(x.to_total_ord()) vs hash_one(x_tot): 1531ms vs 1894ms vs 1715ms vs 1494ms
hash_one(x) vs hash_one(x_wrapped) vs hash_one(x.to_total_ord()) vs hash_one(x_tot): 1509ms vs 1971ms vs 1737ms vs 1527ms
```

* x is i32
* x_wrapped is TotalOrdWrap(x)
* x.to_total_ord() is when we call `x.to_total_ord()` in the loop -> `|| hash_one(x.to_total_ord())`
* x_tot is `let x_tot = x.to_total_ord()` beforehand
The timing for `hash_one(x)` is equivalent to `|| hash_one(x_tot)`, since `x.to_total_ord()` just returns `x` as per `ToTotalOrd::Output`

```rust
mod test {
    #[test]
    fn test() {
        use std::time::SystemTime;

        use super::*;
        let rs = ahash::RandomState::new();

        fn time_it<F: Fn() -> T, T>(f: F, n: u32) -> u128 {
            let start = SystemTime::now();
            for _ in 0..n {
                f();
            }
            let end = SystemTime::now();
            let duration = end.duration_since(start).unwrap();
            return duration.as_millis();
        }

        let x: i32 = 10;
        let x_wrapped = TotalOrdWrap(x);
        let x_tot = x.to_total_ord();
        let n_iterations = 30_000_000;

        for _ in 0..5 {
            let hash_one_t = time_it(|| rs.clone().hash_one(x), n_iterations);
            let hash_one_wrapped_t = time_it(|| rs.clone().hash_one(x_wrapped), n_iterations);
            let hash_one_to_tot_t = time_it(|| rs.clone().hash_one(x.to_total_ord()), n_iterations);
            let hash_one_to_tot_amort_t = time_it(|| rs.clone().hash_one(x_tot), n_iterations);
            println!(
                "hash_one(x) vs hash_one(x_wrapped) vs hash_one(x.to_total_ord()) vs hash_one(x_tot): {}ms vs {}ms vs {}ms vs {}ms",
                hash_one_t, hash_one_wrapped_t, hash_one_to_tot_t, hash_one_to_tot_amort_t
            );
        }
    }
}
```
